import os
import sys
import math
from PIL import Image, ImageDraw, ImageFilter, ImageFont

def draw_glass_panel(base_img, x, y, width, height, radius=24,
                     bg_color=(20, 26, 42, 185),
                     border_color=(255, 255, 255, 60),
                     border_width=1,
                     is_elevated=False,
                     accent_glow=None):
    """
    Renders a VisionOS-style frosted glass floating panel with:
    - Multi-plane elevation shadow
    - Semi-transparent acrylic tint
    - Specular highlights on top border
    - Active accent halo
    """
    # 1. Shadow beneath the panel
    shadow_offset_y = 22 if is_elevated else 10
    shadow_blur = 32 if is_elevated else 18
    shadow_alpha = 110 if is_elevated else 55

    pad = shadow_blur * 2
    shadow_canvas = Image.new('RGBA', (width + pad * 2, height + pad * 2), (0, 0, 0, 0))
    s_draw = ImageDraw.Draw(shadow_canvas)
    s_draw.rounded_rectangle([pad, pad + shadow_offset_y, pad + width, pad + height + shadow_offset_y],
                             radius=radius, fill=(0, 0, 0, shadow_alpha))
    shadow_blurred = shadow_canvas.filter(ImageFilter.GaussianBlur(shadow_blur))
    base_img.alpha_composite(shadow_blurred, (x - pad, y - pad))

    # 2. Accent Glow Halo (for selected card)
    if accent_glow:
        glow_canvas = Image.new('RGBA', (width + pad * 2, height + pad * 2), (0, 0, 0, 0))
        g_draw = ImageDraw.Draw(glow_canvas)
        g_draw.rounded_rectangle([pad, pad, pad + width, pad + height], radius=radius, outline=accent_glow, width=3)
        glow_blurred = glow_canvas.filter(ImageFilter.GaussianBlur(16))
        base_img.alpha_composite(glow_blurred, (x - pad, y - pad))

    # 3. Frosted background region (local blur of background behind the glass)
    sub_bg = base_img.crop((x, y, x + width, y + height))
    sub_bg_blurred = sub_bg.filter(ImageFilter.GaussianBlur(12))

    # Create mask for rounded panel
    mask = Image.new('L', (width, height), 0)
    m_draw = ImageDraw.Draw(mask)
    m_draw.rounded_rectangle([0, 0, width - 1, height - 1], radius=radius, fill=255)

    # Tint overlay
    tint = Image.new('RGBA', (width, height), bg_color)
    sub_bg_blurred.alpha_composite(tint)

    # Specular rim highlight (subtle gradient/top-edge light)
    rim_draw = ImageDraw.Draw(sub_bg_blurred)
    for i in range(border_width):
        rim_draw.rounded_rectangle([i, i, width - 1 - i, height - 1 - i],
                                   radius=radius - i, outline=border_color)

    # Composite frosted panel back onto base
    base_img.paste(sub_bg_blurred, (x, y), mask)

def render_spatial_ui(output_path="spatial_preview.png", screen_w=1920, screen_h=1080, selected_idx=0):
    # Deep, atmospheric spatial horizon background
    bg = Image.new('RGBA', (screen_w, screen_h), (10, 13, 20, 255))
    draw_bg = ImageDraw.Draw(bg)

    # Spatial background gradients (soft celestial horizon & deep nebula)
    for r in range(screen_h):
        factor = r / screen_h
        # Slate blue top to dark abyssal navy bottom
        red = int(14 * (1 - factor) + 8 * factor)
        green = int(22 * (1 - factor) + 12 * factor)
        blue = int(42 * (1 - factor) + 22 * factor)
        draw_bg.line([(0, r), (screen_w, r)], fill=(red, green, blue, 255))

    # Subtle ambient glow in center
    amb = Image.new('RGBA', (screen_w, screen_h), (0, 0, 0, 0))
    amb_draw = ImageDraw.Draw(amb)
    amb_draw.ellipse([screen_w // 2 - 600, int(screen_h * 0.40) - 300,
                      screen_w // 2 + 600, int(screen_h * 0.40) + 300],
                     fill=(35, 75, 140, 50))
    amb = amb.filter(ImageFilter.GaussianBlur(140))
    bg.alpha_composite(amb)

    # Fonts
    try:
        font_large = ImageFont.truetype("/usr/share/fonts/TTF/DejaVuSans-Bold.ttf", 24)
        font_med = ImageFont.truetype("/usr/share/fonts/TTF/DejaVuSans.ttf", 15)
        font_small = ImageFont.truetype("/usr/share/fonts/TTF/DejaVuSans.ttf", 12)
        font_bold = ImageFont.truetype("/usr/share/fonts/TTF/DejaVuSans-Bold.ttf", 13)
    except:
        font_large = ImageFont.load_default()
        font_med = font_large
        font_small = font_large
        font_bold = font_large

    # 1. Top Spatial Status Capsule (Floating Glass Pill)
    pill_w = 480
    pill_h = 44
    pill_x = (screen_w - pill_w) // 2
    pill_y = 40
    draw_glass_panel(bg, pill_x, pill_y, pill_w, pill_h, radius=22,
                     bg_color=(25, 32, 48, 160), border_color=(255, 255, 255, 45))
    draw = ImageDraw.Draw(bg)
    draw.text((pill_x + 28, pill_y + 13), "✦ LIMINE SPATIAL OS DECK", fill=(235, 245, 255, 230), font=font_bold)
    draw.text((pill_x + pill_w - 110, pill_y + 13), "UEFI x86_64", fill=(140, 175, 215, 200), font=font_small)

    # 2. Main Spatial Cards Deck
    icon_base = "/home/skand/CODING/my-limine/Limine/themes/artorias/icons"
    cards = [
        {
            "id": "cachyos",
            "title": "CachyOS Linux",
            "kernel": "7.2.11-cachyos",
            "desc": "Primary Performance Build",
            "accent": (40, 190, 240),
            "tag": "DEFAULT",
            "icon_file": os.path.join(icon_base, "cachyos.png")
        },
        {
            "id": "bore",
            "title": "CachyOS BORE",
            "kernel": "7.2.11-cachyos-bore",
            "desc": "Burst-Oriented Low Latency",
            "accent": (255, 130, 45),
            "tag": "GAMING",
            "icon_file": os.path.join(icon_base, "cachy.png")
        },
        {
            "id": "snapshots",
            "title": "System Snapshots",
            "kernel": "Btrfs Subvolumes",
            "desc": "Instant System Rollback",
            "accent": (150, 130, 250),
            "tag": "BACKUP",
            "icon_file": os.path.join(icon_base, "snapshot.png")
        },
        {
            "id": "uefi",
            "title": "Firmware Setup",
            "kernel": "Motherboard BIOS",
            "desc": "Hardware & Boot Settings",
            "accent": (160, 180, 205),
            "tag": "SYSTEM",
            "icon_file": os.path.join(icon_base, "efi.png")
        }
    ]

    base_card_w = 270
    base_card_h = 350
    gap = 36
    total_deck_w = len(cards) * base_card_w + (len(cards) - 1) * gap
    start_x = (screen_w - total_deck_w) // 2
    deck_y = int(screen_h * 0.28)

    for i, c in enumerate(cards):
        is_sel = (i == selected_idx)

        if is_sel:
            scale = 1.06
            cw = int(base_card_w * scale)
            ch = int(base_card_h * scale)
            cx = start_x + i * (base_card_w + gap) - (cw - base_card_w) // 2
            cy = deck_y - (ch - base_card_h) // 2 - 14
            bg_c = (26, 36, 56, 210)
            border_c = (255, 255, 255, 110)
            glow_c = (60, 180, 255, 190)
        else:
            cw = base_card_w
            ch = base_card_h
            cx = start_x + i * (base_card_w + gap)
            cy = deck_y
            bg_c = (18, 24, 38, 145)
            border_c = (255, 255, 255, 30)
            glow_c = None

        draw_glass_panel(bg, cx, cy, cw, ch, radius=24,
                         bg_color=bg_c, border_color=border_c,
                         is_elevated=is_sel, accent_glow=glow_c)

        c_draw = ImageDraw.Draw(bg)

        # Tag Pill in Card top right
        tag_w = 72
        tag_h = 24
        tag_x = cx + cw - tag_w - 18
        tag_y = cy + 18
        tag_bg = (40, 130, 220, 75) if is_sel else (255, 255, 255, 15)
        c_draw.rounded_rectangle([tag_x, tag_y, tag_x + tag_w, tag_y + tag_h], radius=12, fill=tag_bg)
        c_draw.text((tag_x + 12, tag_y + 4), c["tag"],
                    fill=(210, 235, 255) if is_sel else (135, 145, 160), font=font_bold)

        # Distro Icon Floating Emblem
        icon_cx = cx + cw // 2
